FRAMES = 6
SKY    = 0xBEAF
GROUND = 0x75EF

CACTUS_W = 4
CACTUS_H = 16

CACTUS_DATA = b'\x1f\xf8\x1b\xc7\x1f\xf8\x1f\xf8\x1f\xf8\x1f\xf8\x1f\xf8\x1b\xc7\x1f\xf8\x1f\xf8\x1f\xf8^\x06\x1f\xf8^\x06\x1f\xf8\x1b\xc7\x1f\xf8\x1f\xf8\x1b\xc7\x1f\xf8\x1b\xc7\x1b\xc7\x1f\xf8\x1f\xf8\x1f\xf8\x1b\xc7\x1b\xc7\x1f\xf8\x1b\xc7^\x06\x1b\xc7\x1f\xf8\x1f\xf8\x1b\xc7\x1b\xc7\x1f\xf8\x1f\xf8\x1b\xc7^\x06\x1b\xc7\x1f\xf8\x1b\xc7\x1b\xc7\x1f\xf8\x1f\xf8\x1b\xc7\x1b\xc7\x1f\xf8\x1b\xc7\x1b\xc7^\x06\x1f\xf8\x1f\xf8\x1b\xc7\x1b\xc7\x1b\xc7\x1f\xf8^\x06\x1b\xc7\x1f\xf8\x1f\xf8\x1b\xc7\x1b\xc7\x1f\xf8'

def makecactus():
    x = 240 - 5
    y = 184

    cactus = []
    for _ in range(random.randint(1, 4)):
        cactus.append([])


    for i in range(len(cactus)):
        cactus[i].append(x + i * 5)
        cactus[i].append(y)

    return cactus

def movecactus(cactus, speed):
    for i in range(len(cactus)):
        cactus[i][0] -= speed
    return cactus

def check_collision(dino_y, cacti):
    margin = 3
    dx1 = DINO_X + margin
    dy1 = int(dino_y) + margin
    dx2 = DINO_X + DINO_W - margin
    dy2 = int(dino_y) + DINO_H - margin
    for group in cacti:
        for cactus in group:
            cx2 = cactus[0] + CACTUS_W
            cy2 = cactus[1] + CACTUS_H
            if dx1 < cx2 and dx2 > cactus[0] and dy1 < cy2 and dy2 > cactus[1]:
                return True
    return False
    

def run():
    frame_start = time.ticks_ms()
    dino_y   = float(GROUND_Y - DINO_H)
    dino_v   = 0.0
    frame    = 0
    tick     = 0
    cactus_counter = 40
    score = 0
    targetscore = 300
    speed = 5
    dead = False

    cacti = []

    bufs = [bytearray(f) for f in (_F0, _F1, _F2, _F3, _F4, _F5)]
    fbs  = [framebuf.FrameBuffer(b, DINO_W, DINO_H, framebuf.RGB565) for b in bufs]
    cactus_buf = bytearray(CACTUS_DATA)
    cactus_fb  = framebuf.FrameBuffer(cactus_buf, CACTUS_W, CACTUS_H, framebuf.RGB565)

    while True:
        frame_start = time.ticks_ms()
        # inputs
        on_ground = dino_y >= GROUND_Y - DINO_H
        if (keyA.value() == 0 or up.value() == 0) and on_ground:
            dino_v = JUMP_V

        if keyY.value() == 0:
            return

        # physics
        dino_v += GRAVITY
        dino_y += dino_v
        if dino_y >= GROUND_Y - DINO_H:
            dino_y = GROUND_Y - DINO_H
            dino_v = 0.0

        cactus_counter -= 1

        if cactus_counter < 1:
            cacti.append(makecactus())
            cactus_counter = random.randint(20,50)

        # move cactuses
        for i in range(len(cacti) - 1, -1, -1):
            cacti[i] = movecactus(cacti[i], speed)
            if cacti[i][0][0] < -20:
                cacti.pop(i)

        if check_collision(dino_y, cacti):
            dead = True

        score += 1

        if score > targetscore:
            targetscore += 300
            speed += 1

        # animation — only cycle when on the ground
        if on_ground:
            tick += 1
            if tick >= 2:
                tick = 0
                frame = (frame + 1) % FRAMES
        else:
            frame = 0


        # drawing
        LCD.fill(SKY)
        LCD.fill_rect(0, GROUND_Y, 240, 240 - GROUND_Y, GROUND)
        LCD.blit(fbs[frame], DINO_X, int(dino_y), 0xF81F)

        for i in range(len(cacti)):
            for j in range(len(cacti[i])):
                LCD.blit(cactus_fb, cacti[i][j][0], cacti[i][j][1], 0xF81F)

        LCD.show()

        elapsed = time.ticks_diff(time.ticks_ms(), frame_start)
        if elapsed < 50:
            time.sleep_ms(50 - elapsed)

        if dead:
            death_time = time.ticks_ms()
            while True:
                frame_start = time.ticks_ms()
                LCD.fill(0x0000)
                LCD.text(f"Score: {score}", 56, 112, 0xB965, 2)
                LCD.show()

                if keyY.value() == 0:
                    return

                can_restart = time.ticks_diff(time.ticks_ms(), death_time) > 1000
                if can_restart and keyA.value() == 0:
                    frame_start = time.ticks_ms()
                    dino_y   = float(GROUND_Y - DINO_H)
                    dino_v   = 0.0
                    frame    = 0
                    tick     = 0
                    cactus_counter = 40
                    score = 0
                    targetscore = 500
                    speed = 5

                    cacti = []
                    dead = False
                    break

                elapsed = time.ticks_diff(time.ticks_ms(), frame_start)
                if elapsed < 50:
                    time.sleep_ms(50 - elapsed)
